import 'package:flutter/material.dart'; import '../core/theme/app_theme.dart';
class RadioPlayer extends StatelessWidget { const RadioPlayer({super.key,required this.playing,required this.onPressed}); final bool playing; final VoidCallback onPressed; @override Widget build(BuildContext context)=>Semantics(button:true,label:playing?'Pause live radio':'Play live radio',child:InkWell(onTap:onPressed,borderRadius:BorderRadius.circular(60),child:Container(width:112,height:112,decoration:const BoxDecoration(color:AppColors.crimson,shape:BoxShape.circle),child:Icon(playing?Icons.pause_rounded:Icons.play_arrow_rounded,color:AppColors.cream,size:54)))); }
